var EN={"skip": "Skip to content", "menu": "Menu", "nav.home": "Home", "nav.games": "Games", "nav.about": "About", "nav.beta": "Join the beta", "nav.contact": "Contact", "footer.terms": "Terms of Use", "contact.privacy": "Privacy Policy", "footer.copy": "© 2026 ATTA CORP. All rights reserved. Block Fill, Chroma Shift, Rustroot, Crownless and the ATTA CORP name and logos are property of ATTA CORP.", "footer.tagline": "Indie games that are easy to start and hard to put down.", "footer.studio": "Studio", "footer.games": "Games", "footer.contact": "Contact", "home.kicker": "Indie mobile studio", "home.games": "Our games", "home.gameslead": "Four original games — from one-line puzzles to living worlds. One is live on Google Play, three are in open-to-join closed testing.", "home.allgames": "View all games", "home.aboutcta": "About the studio", "home.learn": "Learn more", "hero.prev": "Previous game", "hero.next": "Next game", "hero.carousel": "Featured games", "games.title": "Games", "games.lead": "Browse the ATTA CORP catalog. Block Fill is live on Google Play; Chroma Shift, Rustroot and Crownless are in free closed testing — you can join today.", "games.dev": "In development — coming soon", "games.live": "Live on Google Play", "games.testing": "Closed beta on Google Play", "games.soon": "Coming soon", "games.beta": "Become a tester", "games.play": "Get it on Google Play", "bf.tag": "Draw one line. Fill every block.", "bf.short": "A calm, clever one-line puzzle with 2,000 levels. Play entirely offline.", "bf.long1": "Block Fill is a calm, clever one-line puzzle: draw a single path that fills every block on the board. No timers, no pressure — just you, a grid and one continuous line.", "bf.long2": "Levels start small so you learn fast, then the grid grows — with more walls and tricky branches. A fresh daily puzzle keeps a streak going, and the game works fully offline, on a plane or on the couch. Hints show the next part of the path, never the whole solution.", "bf.f1": "2,000 levels", "bf.f1d": "From relaxing 4×4 warm-ups to 10×12 brain-twisters. Every level is solvable.", "bf.f2": "Plays offline", "bf.f2d": "No Wi-Fi needed. Your progress is saved on your device.", "bf.f3": "Daily puzzle", "bf.f3d": "A new board every day. Solve it to build your streak.", "bf.f4": "Fair hints", "bf.f4d": "Free hints as you go, or an optional short video for another. Never spoils the whole path.", "cs.tag": "Tap cells. Shift colors. Clear the board.", "cs.short": "A relaxing color puzzle. Soft palettes, no timers, pure flow.", "cs.long1": "Chroma Shift is a colorful logic puzzle from ATTA CORP. Tap any cell to cycle its color — and its neighbors. Match every cell to the target shade to clear the level.", "cs.long2": "Forty handcrafted levels, undo and reset, and optional video hints. English and Russian are built in — pick one in Settings. Ads are served by Google AdMob; you can remove them anytime with a one-time purchase through Google Play. No account required.", "cs.f1": "Calm color puzzles", "cs.f1d": "Shift hues with each tap until the board matches the target.", "cs.f2": "No timers", "cs.f2d": "Play at your own pace. There is no clock and no pressure.", "cs.f3": "English and Russian", "cs.f3d": "Choose your language on the first launch or anytime in Settings.", "cs.f4": "Optional remove-ads", "cs.f4d": "A one-time Google Play purchase hides ads. Tips to the studio are optional too.", "rr.tag": "A colony at the end of the world.", "rr.short": "A mobile colony survival sim. Salvage, farm, build and hold off raiders.", "rr.long1": "Rustroot is a mobile-first colony survival sim set after the collapse. You guide a handful of survivors who salvage ruins, farm hardy tubers, build shelter and hold off raiders — and you watch their story unfold.", "rr.long2": "The world is procedural: day and night, raids that scale with your wealth, a wider map with caravans, and colonists with needs, moods and relationships. It is built for touch and shorter sessions. Rustroot is now in free closed testing on Google Play — become a tester below.", "rr.f1": "Living stories", "rr.f1d": "Colonists work, quarrel, recover and leave a chronicle of the colony you built.", "rr.f2": "Build, farm, defend", "rr.f2d": "Raise walls and crops, craft gear and hold the line when raiders come.", "rr.f3": "A wider wasteland", "rr.f3d": "Explore the world map, send caravans and chase signals in the ruins.", "rr.f4": "Made for mobile", "rr.f4d": "Touch controls, short sessions and a colony that keeps living while you are away.", "cl.tag": "A crown without a master.", "cl.short": "Lead a nameless exile: raise an army, win real-time battles and take back the crown.", "cl.long1": "Crownless is a strategy adventure from ATTA CORP. Five winters ago a usurper betrayed your father, seized your lands and hid the ancient crown behind the walls of Castle Veir. You are a nameless exile — until you raise an army and take it back.", "cl.long2": "Ride a living realm, forge alliances, manage your warband and fight real-time battles you can command by hand or trust to auto-orders. The world and its kingdoms are much larger than a single campaign map. Crownless is now in free closed testing on Google Play — become a tester below.", "cl.f1": "Real-time battles", "cl.f1d": "Deploy squads, hold the line, loose arrows and send cavalry around the flank.", "cl.f2": "A living realm", "cl.f2d": "Travel a 3D world of roads, forests, towns and castles that change with the hour.", "cl.f3": "Armies and allies", "cl.f3d": "Recruit companions, strike bargains with lords and grow a warband that can topple a usurper.", "cl.f4": "Reclaim the crown", "cl.f4d": "The story has a throne at the end of the road — and a world that continues after.", "chip.puzzle": "Puzzle", "chip.levels": "2000 levels", "chip.offline": "Plays offline", "chip.daily": "Daily puzzle", "chip.color": "Color puzzle", "chip.relax": "Relaxing", "chip.enru": "EN / RU", "chip.colony": "Colony sim", "chip.survival": "Survival", "chip.strategy": "Strategy", "chip.battles": "Real-time battles", "chip.world": "Open world", "about.eyebrow": "About the studio", "about.title": "We make games that respect your time", "about.lead": "ATTA CORP is an independent studio. We design, build and polish original mobile games — casual puzzles you can finish on a commute, and deeper worlds you can sink into for weeks. A small team plays every game every day.", "about.f1": "Easy to start", "about.f1d": "No tutorial walls, no sign-ups. Open the game and play within seconds.", "about.f2": "Built to last", "about.f2d": "We polish systems until they stay fun — offline when we can, honest about ads and purchases.", "about.f3": "Built with players", "about.f3d": "We test early with our community and ship updates based on your feedback.", "about.catalog": "The catalog today", "beta.eyebrow": "Testers wanted", "beta.title": "Play our games before everyone else", "beta.lead": "Chroma Shift, Rustroot and Crownless are in free closed testing on Google Play. Join once, pick the games you like, and help us shape the final versions. Please keep each game installed for at least 14 days — that is what Google needs before a launch.", "beta.s1": "Join the testers group", "beta.s1d": "Open the Google Group with the Google account you use on your phone and press “Join group”. One group covers all our test games.", "beta.s1b": "Open the group", "beta.s2": "Opt in on Google Play", "beta.s2d": "Open the game’s testing link with the same account and tap “Become a tester”.", "beta.s2b": "Become a tester", "beta.note": "Why test? You get the game first, your ideas can land in the release, and you help an indie studio get onto Google Play. Found a bug? Write to <a href=\"mailto:gamerazrabplay@gmail.com\">gamerazrabplay@gmail.com</a> with your phone model and Android version.", "contact.eyebrow": "Contact", "contact.title": "Say hello", "contact.lead": "Questions, feedback, bug reports or partnerships — write to us:", "contact.write": "Write an email", "gallery.title": "Screenshots", "gallery.hint": "Swipe to browse. Tap a shot to view it larger.", "gallery.close": "Close", "gallery.prev": "Previous screenshot", "gallery.next": "Next screenshot", "detail.features": "Highlights", "detail.about": "About the game", "detail.privacy": "Privacy Policy", "detail.back": "All games", "crumb.home": "Home", "crumb.games": "Games", "terms.title": "Terms of Use", "terms.updated": "Last updated: 11 November 2026", "terms.who.h": "Who we are", "terms.who": "ATTA CORP is an independent game studio. These Terms of Use govern your use of this website (shaman-atta.github.io) and our games, including Block Fill: One Line Puzzle, Chroma Shift, Rustroot and Crownless (together, the “Games”). For questions, write to <a href=\"mailto:gamerazrabplay@gmail.com\">gamerazrabplay@gmail.com</a>.", "terms.lic.h": "License to use the Games", "terms.lic": "We grant you a personal, limited, revocable, non-exclusive, non-transferable license to install and play the Games for your own non-commercial entertainment, in accordance with these Terms and the Google Play Terms of Service.", "terms.no.h": "What you may not do", "terms.no": "You may not copy, modify, distribute, sell or sublicense the Games or any of their assets; decompile the Games or attempt to extract source code except where the law expressly allows it; cheat, hack or use unofficial modifications that bypass purchases, ads or progression; or use the Games or this site for any unlawful purpose.", "terms.iap.h": "In-app purchases and ads", "terms.iap": "Some Games show ads through Google AdMob and may offer optional in-app purchases through Google Play Billing, such as removing ads or tipping the studio. Prices are shown in the store at the time of purchase. Refunds are handled under Google Play’s refund policy, not directly by ATTA CORP. Purchases are optional; you can play without them.", "terms.ip.h": "Intellectual property", "terms.ip": "The Games, this website, and all code, art, audio, text, names and logos are owned by ATTA CORP or used under license. Block Fill, Chroma Shift, Rustroot, Crownless and the ATTA CORP name and logos are property of ATTA CORP. These Terms do not transfer any ownership to you.", "terms.dis.h": "Disclaimer of warranty", "terms.dis": "The website and the Games are provided “as is” and “as available”, without warranties of any kind, whether express or implied, including merchantability, fitness for a particular purpose and non-infringement. We do not warrant that they will be uninterrupted, error-free or completely secure.", "terms.lim.h": "Limitation of liability", "terms.lim": "To the fullest extent permitted by law, ATTA CORP will not be liable for any indirect, incidental, special, consequential or punitive damages, or for any loss of data, profits or goodwill, arising from your use of the website or the Games. Our total liability for any claim will not exceed the amount you paid us for the relevant Game in the twelve months before the claim (or zero, if you paid nothing).", "terms.chg.h": "Changes to these Terms", "terms.chg": "We may update these Terms from time to time. The “Last updated” date at the top will change when we do. Continued use of the website or the Games after an update means you accept the revised Terms.", "terms.law.h": "Governing law", "terms.law": "These Terms are governed by the laws of the State of Israel, without regard to conflict-of-law rules.", "terms.priv.h": "Privacy", "terms.priv": "How we handle information is described in our <a href=\"https://docs.google.com/document/d/e/2PACX-1vQFyx_OraATnVTC8bk7JEnLfzms0jhiuWvJHve6IIbQMuECAtlIIs1EeHyM6qAs9jxGlwM6PNDAX3Y2/pub\" rel=\"noopener\" target=\"_blank\">Privacy Policy</a>.", "nav.news": "News", "footer.press": "Press kit", "footer.support": "Support", "footer.privacyall": "Privacy policies", "games.support": "Support & FAQ", "home.news": "Latest news", "home.allnews": "All news", "video.title": "Gameplay video", "video.hint": "Real in-game footage from the current beta build.", "tb.title": "Become a tester", "tb.lead": "This game is in free closed testing on Google Play. It takes about a minute:", "beta.s3": "Install and keep it", "beta.s3d": "After you opt in, the testing page shows a “Download it on Google Play” link (it can take a few minutes to appear). Install, play a bit and keep the game installed for 14 days.", "beta.s3b": "Open in Google Play", "beta.pick": "Pick your games", "beta.pickd": "Step 1 (the group) is the same for every game. Then use the game’s own buttons:", "beta.page": "Game page", "beta.leave": "Want to stop testing? Open the same testing link and choose “Leave the program”.", "cs.beta": "Relaxing color puzzle · 40 handcrafted levels", "rr.beta": "Colony survival sim · plays offline", "cl.beta": "Medieval sandbox strategy · real-time battles", "news.title": "News", "news.lead": "Updates, releases and calls for testers from the studio.", "news.more": "Read more", "news.devlog": "Read the devlog on itch.io", "n1.t": "Block Fill 1.0.4 sent to Google Play review", "n1.b": "Version 1.0.4 fixes the Remove Ads button in Settings: it now shows the price when Google Play has loaded it, or a clear message if purchases are not available yet. The update will roll out once Google approves it.", "n2.t": "Block Fill 1.0.3 is live on Google Play", "n2.b": "Stability and purchase fixes. The game now re-checks your purchases with Google Play, so Remove Ads stays tied to your Google account.", "n3.t": "Crownless closed beta: testers wanted", "n3.b": "Crownless: Medieval Kingdoms is in free closed testing on Google Play (build 0.21.2). Raise an army, fight lords and bandits and win back your family’s lost crown. We would love feedback on crashes, performance, the tutorial and battle balance.", "n4.t": "Three games are open for testers", "n4.b": "Chroma Shift, Rustroot and Crownless are all in closed testing on Google Play. One Google Group gives access to all three — the beta page has the steps.", "n5.t": "New on the site: news, support pages and a press kit", "n5.b": "Every game now has a support and FAQ page, a privacy policy link, a gameplay gallery — and there is a press kit for creators and journalists.", "sup.eyebrow": "Support", "sup.title": "Support & FAQ", "sup.contact": "Still need help?", "sup.contactd": "Write to us — we read every message. Please add your phone model, Android version and the game version (Settings or the Google Play page).", "sup.write": "Email support", "sup.faq": "Frequently asked questions", "sup.privacy": "Privacy policy", "sup.game": "Game page", "sup.all": "Support for other games", "faq.refund.q": "How do I get a refund?", "faq.refund.a": "All purchases are processed by Google Play. You can request a refund from your <a href=\"https://play.google.com/store/account/orderhistory\" rel=\"noopener\" target=\"_blank\">Google Play order history</a>. If something went wrong, email us too.", "faq.data.q": "What data do you keep? How do I delete it?", "faq.data.a": "We don’t run accounts or keep your personal data on our servers. Progress is stored on your phone; uninstalling the game or clearing its data deletes it. Ads and payments are handled by Google — see the privacy policy for details.", "faq.bug.q": "How do I report a bug?", "faq.bug.a": "Email <a href=\"mailto:gamerazrabplay@gmail.com\">gamerazrabplay@gmail.com</a> with a short description, your phone model, Android version and, if possible, a screenshot.", "faq.beta.q": "How do I join the beta?", "faq.beta.a": "Join our <a href=\"https://groups.google.com/g/chroma-shift-testers\" rel=\"noopener\" target=\"_blank\">Google Group</a>, then open the testing link on the <a href=\"../beta.html\">beta page</a> with the same account and tap “Become a tester”.", "faq.leave.q": "How do I leave the beta?", "faq.leave.a": "Open the same testing link and choose “Leave the program”. You can then reinstall the public version when the game launches.", "faq.offline.q": "Does the game work offline?", "bf.faq.offline": "Yes. Block Fill plays fully offline. An internet connection is only needed for ads and purchases.", "bf.faq.ads.q": "How do I remove ads?", "bf.faq.ads.a": "Open Settings and tap “Remove Ads” — it is a one-time purchase through Google Play. If the button says “Loading…” or “Unavailable”, check your internet connection and Google Play sign-in, then try again.", "bf.faq.restore.q": "I bought Remove Ads but still see ads", "bf.faq.restore.a": "Make sure the phone is signed in to the same Google account you used to buy, then open the game with internet on — it re-checks your purchases with Google Play automatically.", "bf.faq.progress.q": "Will my progress carry over to a new phone?", "bf.faq.progress.a": "Progress is saved on your device only, so a new phone starts from level 1. Your Remove Ads purchase stays with your Google account.", "bf.faq.hint.q": "How do hints work?", "bf.faq.hint.a": "A hint shows the next part of the path, never the whole solution. You get free hints, and you can watch an optional short video for another.", "cs.faq.play.q": "How do I play?", "cs.faq.play.a": "Tap a cell to cycle its color — and its neighbors. Make every cell match the target shade to clear the level. Undo and reset are always available.", "cs.faq.lang.q": "How do I change the language?", "cs.faq.lang.a": "Open Settings in the game and pick English or Русский.", "cs.faq.ads.q": "How do I remove ads?", "cs.faq.ads.a": "Use “Remove Ads” in the game — a one-time purchase through Google Play. Tips to the studio are optional.", "rr.faq.offline": "Yes. Rustroot plays fully offline and has 3 save slots.", "rr.faq.lang.q": "Which languages are supported?", "rr.faq.lang.a": "19 languages, including English, Русский, Español, Deutsch, Français and 日本語.", "rr.faq.save.q": "Can I back up my colony?", "rr.faq.save.a": "Yes — use save export in the game. Saves are stored on your phone, so export before uninstalling.", "cl.faq.offline": "Yes. Crownless plays fully offline, with no ads.", "cl.faq.lang.q": "Which languages are supported?", "cl.faq.lang.a": "7 languages: English, Русский, Español, Português (Brasil), Deutsch, Français and Türkçe.", "cl.faq.perf.q": "The game runs slowly on my phone", "cl.faq.perf.a": "Crownless is a 3D game and big battles are demanding. Please email us your phone model — performance reports from testers help us optimise.", "priv.title": "Privacy policies", "priv.lead": "Each game has its own privacy policy. In short: we don’t run accounts or collect personal data ourselves; ads and payments are handled by Google.", "priv.studio": "Studio-wide privacy policy", "priv.site": "This website", "priv.sited": "The site uses no cookies and no tracking scripts. To count page views it loads a tiny image from the open-source counter hits.sh, which counts loads per page and does not identify you. Your language choice is stored only in your browser.", "press.title": "Press kit", "press.lead": "Everything you need to write about ATTA CORP and our games: logos, descriptions, key facts and screenshots. Free to use for coverage and videos.", "press.zip": "Download the press kit (.zip)", "press.zipd": "Logos, icons, feature graphics, screenshots and descriptions.", "press.facts": "Studio facts", "press.f.dev": "Developer", "press.f.play": "Google Play developer name", "press.f.games": "Games", "press.f.platform": "Platform", "press.f.contact": "Press contact", "press.f.web": "Website", "press.logos": "Logos", "press.logo.svg": "Logo (SVG)", "press.logo.png": "Logo (PNG, 1024 px)", "press.short": "Short description", "press.long": "Description", "press.keyfacts": "Key facts", "press.shots": "Screenshots", "press.icon": "Icon (512 px)", "press.feature": "Feature graphic", "press.studio.short": "ATTA CORP is an independent studio making original mobile games.", "press.studio.long": "ATTA CORP designs, builds and polishes original Android games — casual puzzles you can finish on a commute and deeper worlds you can sink into for weeks. Block Fill is live on Google Play; Chroma Shift, Rustroot and Crownless are in closed testing.", "press.k.genre": "Genre", "press.k.status": "Status", "press.k.price": "Price", "press.k.lang": "Languages", "press.bf.genre": "Puzzle", "press.bf.price": "Free, with ads; optional Remove Ads purchase", "press.bf.lang": "English", "press.cs.genre": "Color logic puzzle", "press.cs.price": "Free, with ads; optional Remove Ads and tip purchases", "press.cs.lang": "English, Русский", "press.rr.genre": "Colony survival sim", "press.rr.price": "Free during the beta", "press.rr.lang": "19 languages", "press.cl.genre": "Medieval sandbox strategy RPG", "press.cl.price": "Free during the beta, no ads", "press.cl.lang": "7 languages", "press.status.live": "Live on Google Play", "press.status.beta": "Closed testing on Google Play", "press.bf.short": "Draw one line. Fill every block. A calm one-line puzzle with 2,000 levels that plays fully offline.", "press.cs.short": "Tap cells, shift colors, clear the board. A calm color puzzle with 40 handcrafted levels.", "press.rr.short": "Lead survivors after the collapse: scavenge, farm, build and hold off raiders.", "press.cl.short": "Raise an army, fight lords and bandits, and win back your family’s lost crown.", "press.rr.long": "Rustroot is a top-down colony survival sim built for phones. Colonists eat, sleep, get tired, make friends and break down under stress. Scavenge ruins, farm, build walls, workshops and turrets, research three eras of tech, defend against raiders and harsh winters, and send caravans across the world map. Plays fully offline.", "press.cl.long": "Crownless is a medieval sandbox strategy RPG for phones. Ride across a living 3D world of five kingdoms, 74 towns, villages and castles and 15 lords with their own plans. Recruit infantry, archers and cavalry, fight real-time battles, besiege castles, trade and take on quests. Plays fully offline, no ads.", "kofi.eyebrow": "Support the studio", "kofi.title": "Help us make more games", "kofi.lead": "If you enjoy our games, you can support ATTA CORP on Ko-fi. It helps us keep shipping updates and new titles.", "kofi.btn": "Support ATTA CORP on Ko-fi", "kofi.short": "Support on Ko-fi"};
var RU={"skip": "Перейти к содержимому", "menu": "Меню", "nav.home": "Главная", "nav.games": "Игры", "nav.about": "О студии", "nav.beta": "Бета-тест", "nav.contact": "Контакты", "footer.terms": "Условия использования", "contact.privacy": "Политика конфиденциальности", "footer.copy": "© 2026 ATTA CORP. Все права защищены. Block Fill, Chroma Shift, Rustroot, Crownless, а также название и логотипы ATTA CORP являются собственностью ATTA CORP.", "footer.tagline": "Инди-игры, в которые легко начать играть и трудно оторваться.", "footer.studio": "Студия", "footer.games": "Игры", "footer.contact": "Контакты", "home.kicker": "Инди-студия мобильных игр", "home.games": "Наши игры", "home.gameslead": "Четыре оригинальные игры — от головоломок в одну линию до живых миров. Одна уже в Google Play, три — в закрытом тесте, куда может вступить каждый.", "home.allgames": "Все игры", "home.aboutcta": "О студии", "home.learn": "Подробнее", "hero.prev": "Предыдущая игра", "hero.next": "Следующая игра", "hero.carousel": "Избранные игры", "games.title": "Игры", "games.lead": "Каталог ATTA CORP. Block Fill уже в Google Play, а Chroma Shift, Rustroot и Crownless проходят бесплатное закрытое тестирование — присоединяйся.", "games.dev": "В разработке — скоро", "games.live": "Уже в Google Play", "games.testing": "Закрытая бета в Google Play", "games.soon": "Скоро", "games.beta": "Стать тестировщиком", "games.play": "Скачать в Google Play", "bf.tag": "Проведи одну линию. Заполни все блоки.", "bf.short": "Спокойная и умная головоломка в одну линию на 2000 уровней. Полностью без интернета.", "bf.long1": "Block Fill — спокойная и умная головоломка в одну линию: проведи один путь, который заполняет все блоки на поле. Без таймеров и спешки — только ты, сетка и одна непрерывная линия.", "bf.long2": "Уровни начинаются с малого, чтобы быстро освоиться, затем поле растёт — появляется больше стен и развилок. Каждый день новая головоломка поддерживает серию побед, а игра полностью работает без интернета — в самолёте или на диване. Подсказка показывает только следующий отрезок пути, а не всё решение.", "bf.f1": "2000 уровней", "bf.f1d": "От расслабляющих разминок 4×4 до головоломок 10×12. Каждый уровень решаем.", "bf.f2": "Работает офлайн", "bf.f2d": "Интернет не нужен. Прогресс сохраняется на устройстве.", "bf.f3": "Ежедневная головоломка", "bf.f3d": "Новое поле каждый день. Решай и копи серию побед.", "bf.f4": "Честные подсказки", "bf.f4d": "Бесплатные подсказки по ходу игры или короткое видео за ещё одну. Никогда не раскрывает весь путь.", "cs.tag": "Нажимай клетки. Сдвигай цвета. Очисти поле.", "cs.short": "Расслабляющая цветовая головоломка. Мягкие палитры, без таймеров — только поток.", "cs.long1": "Chroma Shift — цветная логическая головоломка от ATTA CORP. Нажмите клетку — сменится её цвет и цвет соседей. Сделайте все клетки целевого оттенка, чтобы пройти уровень.", "cs.long2": "Сорок авторских уровней, отмена и сброс, а также необязательные подсказки за видео. Английский и русский уже в игре — язык выбирается в настройках. Реклама через Google AdMob; её можно убрать разовой покупкой в Google Play. Аккаунт не нужен.", "cs.f1": "Спокойные цветовые головоломки", "cs.f1d": "Сдвигай оттенки нажатиями, пока поле не совпадёт с целью.", "cs.f2": "Без таймеров", "cs.f2d": "Играй в своём темпе. Без часов и без давления.", "cs.f3": "Английский и русский", "cs.f3d": "Выбери язык при первом запуске или в любой момент в настройках.", "cs.f4": "Рекламу можно отключить", "cs.f4d": "Разовая покупка в Google Play скрывает рекламу. Донат студии тоже необязателен.", "rr.tag": "Колония на краю света.", "rr.short": "Мобильный симулятор колонии на выживание. Собирай лом, строй и отбивай налёты.", "rr.long1": "Rustroot — мобильный симулятор колонии после катастрофы. Ты ведёшь горстку выживших: они разбирают руины, выращивают стойкие клубни, строят укрытие и отбивают налёты — а ты смотришь, как складывается их история.", "rr.long2": "Мир процедурный: день и ночь, налёты, которые растут вместе с богатством колонии, карта мира с караванами, колонисты с потребностями, настроением и отношениями. Игра сделана под сенсор и короткие сессии. Rustroot уже проходит бесплатное закрытое тестирование в Google Play — стань тестировщиком ниже.", "rr.f1": "Живые истории", "rr.f1d": "Колонисты работают, ссорятся, поправляются и оставляют летопись колонии, которую ты построил.", "rr.f2": "Строй, сей, защищай", "rr.f2d": "Возводи стены, выращивай урожай, делай снаряжение и держи оборону, когда приходят налётчики.", "rr.f3": "Большая пустошь", "rr.f3d": "Исследуй карту мира, отправляй караваны и иди на сигналы в руинах.", "rr.f4": "Сделано для телефона", "rr.f4d": "Управление пальцем, короткие сессии и колония, которая живёт, пока тебя нет.", "cl.tag": "Корона без хозяина.", "cl.short": "Веди безымянного изгнанника: собери войско, побеждай в боях и верни корону.", "cl.long1": "Crownless — стратегическое приключение от ATTA CORP. Пять зим назад узурпатор предал твоего отца, захватил земли и спрятал древнюю корону за стенами Замка Вейр. Ты безымянный изгнанник — пока не соберёшь войско и не вернёшь своё.", "cl.long2": "Путешествуй по живому краю, заключай союзы, управляй отрядом и сражайся в боях в реальном времени — сам или через автоприказы. Мир и его королевства гораздо больше одной кампании. Crownless уже проходит бесплатное закрытое тестирование в Google Play — стань тестировщиком ниже.", "cl.f1": "Бои в реальном времени", "cl.f1d": "Расставляй отряды, держи строй, дай залп лучников и зайди конницей во фланг.", "cl.f2": "Живой край", "cl.f2d": "Путешествуй по трёхмерному миру дорог, лесов, городов и замков, который меняется со временем суток.", "cl.f3": "Войска и союзники", "cl.f3d": "Набирай спутников, договаривайся с лордами и собери войско, которому по силам свергнуть узурпатора.", "cl.f4": "Верни корону", "cl.f4d": "В конце пути — престол, а мир не заканчивается вместе с историей.", "chip.puzzle": "Головоломка", "chip.levels": "2000 уровней", "chip.offline": "Без интернета", "chip.daily": "Ежедневная головоломка", "chip.color": "Цветовая головоломка", "chip.relax": "Расслабляет", "chip.enru": "EN / RU", "chip.colony": "Симулятор колонии", "chip.survival": "Выживание", "chip.strategy": "Стратегия", "chip.battles": "Бои в реальном времени", "chip.world": "Открытый мир", "about.eyebrow": "О студии", "about.title": "Мы делаем игры, которые ценят ваше время", "about.lead": "ATTA CORP — независимая студия. Мы придумываем, делаем и шлифуем оригинальные мобильные игры: казуальные головоломки для дороги и более глубокие миры, в которые можно погрузиться на недели. Небольшая команда сама играет в каждую игру каждый день.", "about.f1": "Легко начать", "about.f1d": "Без длинных обучений и регистраций. Открыл игру — и уже играешь.", "about.f2": "Делаем надолго", "about.f2d": "Мы доводим системы, пока в них интересно играть месяцами — офлайн, где возможно, и честно по поводу рекламы и покупок.", "about.f3": "Вместе с игроками", "about.f3d": "Мы рано тестируем игры с сообществом и выпускаем обновления по вашим отзывам.", "about.catalog": "Каталог сегодня", "beta.eyebrow": "Ищем тестировщиков", "beta.title": "Играй в наши игры раньше всех", "beta.lead": "Chroma Shift, Rustroot и Crownless проходят бесплатное закрытое тестирование в Google Play. Вступи один раз, выбери понравившиеся игры и помоги нам сделать финальные версии. Пожалуйста, не удаляй каждую игру хотя бы 14 дней — это нужно Google перед релизом.", "beta.s1": "Вступи в группу тестировщиков", "beta.s1d": "Открой Google-группу под тем Google-аккаунтом, который стоит на телефоне, и нажми «Вступить в группу». Одна группа открывает доступ ко всем нашим тестовым играм.", "beta.s1b": "Открыть группу", "beta.s2": "Подпишись на тест в Google Play", "beta.s2d": "Открой ссылку на тест игры под тем же аккаунтом и нажми «Стать тестировщиком».", "beta.s2b": "Стать тестировщиком", "beta.note": "Зачем тестировать? Ты получаешь игру первым, твои идеи могут попасть в релиз, и ты помогаешь инди-студии выйти в Google Play. Нашёл ошибку? Напиши на <a href=\"mailto:gamerazrabplay@gmail.com\">gamerazrabplay@gmail.com</a> и укажи модель телефона и версию Android.", "contact.eyebrow": "Контакты", "contact.title": "Напиши нам", "contact.lead": "Вопросы, отзывы, сообщения об ошибках или сотрудничество — пиши:", "contact.write": "Написать письмо", "gallery.title": "Скриншоты", "gallery.hint": "Листай галерею. Нажми на кадр, чтобы открыть его крупно.", "gallery.close": "Закрыть", "gallery.prev": "Предыдущий скриншот", "gallery.next": "Следующий скриншот", "detail.features": "Особенности", "detail.about": "Об игре", "detail.privacy": "Политика конфиденциальности", "detail.back": "Все игры", "crumb.home": "Главная", "crumb.games": "Игры", "terms.title": "Условия использования", "terms.updated": "Последнее обновление: 11 ноября 2026 г.", "terms.who.h": "Кто мы", "terms.who": "ATTA CORP — независимая игровая студия. Настоящие Условия использования регулируют пользование этим сайтом (shaman-atta.github.io) и нашими играми, в том числе Block Fill: One Line Puzzle, Chroma Shift, Rustroot и Crownless (далее — «Игры»). Вопросы можно присылать на <a href=\"mailto:gamerazrabplay@gmail.com\">gamerazrabplay@gmail.com</a>.", "terms.lic.h": "Лицензия на использование Игр", "terms.lic": "Мы предоставляем вам личную, ограниченную, отзывную, неисключительную и непередаваемую лицензию устанавливать Игры и играть в них для собственного некоммерческого развлечения — в соответствии с настоящими Условиями и Условиями использования Google Play.", "terms.no.h": "Что запрещено", "terms.no": "Запрещается копировать, изменять, распространять, продавать или сублицензировать Игры и любые их материалы; декомпилировать Игры или иным образом извлекать исходный код, кроме случаев, прямо разрешённых законом; использовать читы, взлом или неофициальные изменения, которые обходят покупки, рекламу или прогресс; а также использовать Игры или этот сайт в незаконных целях.", "terms.iap.h": "Покупки в приложении и реклама", "terms.iap": "В некоторых Играх показывается реклама через Google AdMob, а также могут предлагаться необязательные покупки через Google Play Billing — например, отключение рекламы или донат студии. Цена отображается в магазине в момент покупки. Возвраты рассматриваются по политике возвратов Google Play, а не напрямую ATTA CORP. Покупки необязательны: в игры можно играть и без них.", "terms.ip.h": "Интеллектуальная собственность", "terms.ip": "Игры, этот сайт, а также весь код, графика, звук, тексты, названия и логотипы принадлежат ATTA CORP либо используются по лицензии. Block Fill, Chroma Shift, Rustroot, Crownless, а также название и логотипы ATTA CORP являются собственностью ATTA CORP. Настоящие Условия не передают вам никаких прав собственности.", "terms.dis.h": "Отказ от гарантий", "terms.dis": "Сайт и Игры предоставляются «как есть» и «как доступно», без каких-либо гарантий, явных или подразумеваемых, включая товарную пригодность, пригодность для конкретной цели и ненарушение прав. Мы не гарантируем бесперебойную, безошибочную или полностью безопасную работу.", "terms.lim.h": "Ограничение ответственности", "terms.lim": "В максимальной степени, допускаемой законом, ATTA CORP не несёт ответственности за косвенные, случайные, специальные, последующие или штрафные убытки, а также за утрату данных, прибыли или деловой репутации, возникшие в связи с использованием сайта или Игр. Совокупная ответственность по любому требованию не превысит сумму, которую вы уплатили нам за соответствующую Игру за двенадцать месяцев до требования (или ноль, если вы ничего не платили).", "terms.chg.h": "Изменения Условий", "terms.chg": "Мы можем время от времени обновлять эти Условия. При этом меняется дата «Последнее обновление» в начале страницы. Продолжая пользоваться сайтом или Играми после обновления, вы принимаете новую редакцию.", "terms.law.h": "Применимое право", "terms.law": "Настоящие Условия регулируются законодательством Государства Израиль без учёта коллизионных норм.", "terms.priv.h": "Конфиденциальность", "terms.priv": "То, как мы обрабатываем сведения, описано в нашей <a href=\"https://docs.google.com/document/d/e/2PACX-1vQFyx_OraATnVTC8bk7JEnLfzms0jhiuWvJHve6IIbQMuECAtlIIs1EeHyM6qAs9jxGlwM6PNDAX3Y2/pub\" rel=\"noopener\" target=\"_blank\">Политике конфиденциальности</a>.", "nav.news": "Новости", "footer.press": "Пресс-кит", "footer.support": "Поддержка", "footer.privacyall": "Политики конфиденциальности", "games.support": "Поддержка и FAQ", "home.news": "Последние новости", "home.allnews": "Все новости", "video.title": "Видео геймплея", "video.hint": "Настоящие кадры из текущей бета-версии.", "tb.title": "Стань тестировщиком", "tb.lead": "Игра проходит бесплатное закрытое тестирование в Google Play. Это займёт около минуты:", "beta.s3": "Установи и не удаляй", "beta.s3d": "После подписки на странице теста появится ссылка «Скачать в Google Play» (иногда через несколько минут). Установи игру, поиграй и не удаляй её 14 дней.", "beta.s3b": "Открыть в Google Play", "beta.pick": "Выбери игры", "beta.pickd": "Шаг 1 (группа) общий для всех игр. Дальше — кнопки конкретной игры:", "beta.page": "Страница игры", "beta.leave": "Хочешь выйти из теста? Открой ту же ссылку и выбери «Покинуть программу».", "cs.beta": "Спокойная цветная головоломка · 40 уровней", "rr.beta": "Выживание колонии · играет без интернета", "cl.beta": "Средневековая стратегия-песочница · бои в реальном времени", "news.title": "Новости", "news.lead": "Обновления, релизы и наборы тестировщиков от студии.", "news.more": "Подробнее", "news.devlog": "Девлог на itch.io", "n1.t": "Block Fill 1.0.4 отправлен на проверку в Google Play", "n1.b": "Версия 1.0.4 исправляет кнопку «Убрать рекламу» в настройках: теперь она показывает цену, когда Google Play её загрузил, или понятное сообщение, если покупки пока недоступны. Обновление выйдет после одобрения Google.", "n2.t": "Block Fill 1.0.3 вышел в Google Play", "n2.b": "Исправления стабильности и покупок. Игра теперь перепроверяет покупки через Google Play, так что «Убрать рекламу» надёжно привязана к твоему Google-аккаунту.", "n3.t": "Закрытая бета Crownless: ищем тестировщиков", "n3.b": "Crownless: Medieval Kingdoms проходит бесплатное закрытое тестирование в Google Play (сборка 0.21.2). Собери армию, сражайся с лордами и бандитами и верни утраченную корону рода. Нам важны отзывы о вылетах, производительности, обучении и балансе боёв.", "n4.t": "Три игры открыты для тестировщиков", "n4.b": "Chroma Shift, Rustroot и Crownless проходят закрытое тестирование в Google Play. Одна Google-группа открывает доступ ко всем трём — шаги на странице бета-теста.", "n5.t": "Новое на сайте: новости, поддержка и пресс-кит", "n5.b": "У каждой игры теперь есть страница поддержки с FAQ, ссылка на политику конфиденциальности, галерея — а для блогеров и журналистов появился пресс-кит.", "sup.eyebrow": "Поддержка", "sup.title": "Поддержка и FAQ", "sup.contact": "Нужна помощь?", "sup.contactd": "Напиши нам — мы читаем каждое письмо. Укажи модель телефона, версию Android и версию игры (в настройках или на странице Google Play).", "sup.write": "Написать в поддержку", "sup.faq": "Частые вопросы", "sup.privacy": "Политика конфиденциальности", "sup.game": "Страница игры", "sup.all": "Поддержка других игр", "faq.refund.q": "Как вернуть деньги за покупку?", "faq.refund.a": "Все покупки проходят через Google Play. Запросить возврат можно в <a href=\"https://play.google.com/store/account/orderhistory\" rel=\"noopener\" target=\"_blank\">истории заказов Google Play</a>. Если что-то пошло не так — напиши и нам.", "faq.data.q": "Какие данные вы храните? Как их удалить?", "faq.data.a": "У нас нет аккаунтов, и мы не храним твои личные данные на своих серверах. Прогресс хранится на телефоне; удаление игры или очистка её данных стирает его. Рекламой и платежами занимается Google — подробности в политике конфиденциальности.", "faq.bug.q": "Как сообщить об ошибке?", "faq.bug.a": "Напиши на <a href=\"mailto:gamerazrabplay@gmail.com\">gamerazrabplay@gmail.com</a>: коротко опиши проблему, укажи модель телефона, версию Android и, если можешь, приложи скриншот.", "faq.beta.q": "Как попасть в бету?", "faq.beta.a": "Вступи в нашу <a href=\"https://groups.google.com/g/chroma-shift-testers\" rel=\"noopener\" target=\"_blank\">Google-группу</a>, затем открой ссылку на тест на <a href=\"../beta.html\">странице бета-теста</a> под тем же аккаунтом и нажми «Стать тестировщиком».", "faq.leave.q": "Как выйти из беты?", "faq.leave.a": "Открой ту же ссылку на тест и выбери «Покинуть программу». После релиза можно будет установить обычную версию.", "faq.offline.q": "Игра работает без интернета?", "bf.faq.offline": "Да. Block Fill полностью работает без интернета. Интернет нужен только для рекламы и покупок.", "bf.faq.ads.q": "Как убрать рекламу?", "bf.faq.ads.a": "Открой настройки и нажми «Убрать рекламу» — это разовая покупка через Google Play. Если на кнопке написано «Загрузка…» или «Недоступно», проверь интернет и вход в Google Play и попробуй ещё раз.", "bf.faq.restore.q": "Я купил отключение рекламы, но реклама есть", "bf.faq.restore.a": "Проверь, что на телефоне выполнен вход в тот же Google-аккаунт, с которого была покупка, и открой игру с включённым интернетом — она сама перепроверит покупки в Google Play.", "bf.faq.progress.q": "Перенесётся ли прогресс на новый телефон?", "bf.faq.progress.a": "Прогресс хранится только на устройстве, поэтому на новом телефоне игра начнётся с 1 уровня. Покупка «Убрать рекламу» остаётся на твоём Google-аккаунте.", "bf.faq.hint.q": "Как работают подсказки?", "bf.faq.hint.a": "Подсказка показывает следующий участок пути, но никогда не всё решение. Есть бесплатные подсказки, а ещё одну можно получить за короткое видео по желанию.", "cs.faq.play.q": "Как играть?", "cs.faq.play.a": "Нажми на клетку — сменится её цвет и цвет соседей. Сделай все клетки целевого оттенка, чтобы пройти уровень. Отмена хода и сброс доступны всегда.", "cs.faq.lang.q": "Как сменить язык?", "cs.faq.lang.a": "Открой настройки в игре и выбери English или Русский.", "cs.faq.ads.q": "Как убрать рекламу?", "cs.faq.ads.a": "Нажми «Убрать рекламу» в игре — это разовая покупка через Google Play. Чаевые студии — по желанию.", "rr.faq.offline": "Да. Rustroot полностью работает без интернета, есть 3 слота сохранений.", "rr.faq.lang.q": "Какие языки поддерживаются?", "rr.faq.lang.a": "19 языков, включая English, Русский, Español, Deutsch, Français и 日本語.", "rr.faq.save.q": "Можно сделать резервную копию колонии?", "rr.faq.save.a": "Да — используй экспорт сохранения в игре. Сохранения хранятся на телефоне, поэтому экспортируй их перед удалением игры.", "cl.faq.offline": "Да. Crownless полностью работает без интернета, рекламы нет.", "cl.faq.lang.q": "Какие языки поддерживаются?", "cl.faq.lang.a": "7 языков: English, Русский, Español, Português (Brasil), Deutsch, Français и Türkçe.", "cl.faq.perf.q": "Игра тормозит на моём телефоне", "cl.faq.perf.a": "Crownless — 3D-игра, и большие битвы требовательны к железу. Пришли нам модель телефона — отчёты тестировщиков помогают нам оптимизировать игру.", "priv.title": "Политики конфиденциальности", "priv.lead": "У каждой игры своя политика конфиденциальности. Коротко: у нас нет аккаунтов и мы сами не собираем личные данные; рекламой и платежами занимается Google.", "priv.studio": "Общая политика студии", "priv.site": "Этот сайт", "priv.sited": "Сайт не использует cookie и скрипты слежения. Для подсчёта просмотров он загружает крошечную картинку с открытого счётчика hits.sh, который считает загрузки страниц и не определяет, кто ты. Выбранный язык хранится только в твоём браузере.", "press.title": "Пресс-кит", "press.lead": "Всё, чтобы написать об ATTA CORP и наших играх: логотипы, описания, ключевые факты и скриншоты. Можно свободно использовать в обзорах и видео.", "press.zip": "Скачать пресс-кит (.zip)", "press.zipd": "Логотипы, иконки, баннеры, скриншоты и описания.", "press.facts": "О студии", "press.f.dev": "Разработчик", "press.f.play": "Имя разработчика в Google Play", "press.f.games": "Игры", "press.f.platform": "Платформа", "press.f.contact": "Контакт для прессы", "press.f.web": "Сайт", "press.logos": "Логотипы", "press.logo.svg": "Логотип (SVG)", "press.logo.png": "Логотип (PNG, 1024 px)", "press.short": "Короткое описание", "press.long": "Описание", "press.keyfacts": "Ключевые факты", "press.shots": "Скриншоты", "press.icon": "Иконка (512 px)", "press.feature": "Баннер", "press.studio.short": "ATTA CORP — независимая студия, которая делает оригинальные мобильные игры.", "press.studio.long": "ATTA CORP придумывает, делает и шлифует оригинальные игры для Android — казуальные головоломки на одну поездку и глубокие миры на недели. Block Fill уже в Google Play; Chroma Shift, Rustroot и Crownless проходят закрытое тестирование.", "press.k.genre": "Жанр", "press.k.status": "Статус", "press.k.price": "Цена", "press.k.lang": "Языки", "press.bf.genre": "Головоломка", "press.bf.price": "Бесплатно, с рекламой; покупка «Убрать рекламу» по желанию", "press.bf.lang": "Английский", "press.cs.genre": "Цветная логическая головоломка", "press.cs.price": "Бесплатно, с рекламой; покупки «Убрать рекламу» и чаевые по желанию", "press.cs.lang": "English, Русский", "press.rr.genre": "Симулятор выживания колонии", "press.rr.price": "Бесплатно во время беты", "press.rr.lang": "19 языков", "press.cl.genre": "Средневековая стратегия-песочница с RPG", "press.cl.price": "Бесплатно во время беты, без рекламы", "press.cl.lang": "7 языков", "press.status.live": "В Google Play", "press.status.beta": "Закрытое тестирование в Google Play", "press.bf.short": "Проведи одну линию. Заполни все клетки. Спокойная головоломка на 2000 уровней, полностью без интернета.", "press.cs.short": "Нажимай клетки, сдвигай цвета, очисти поле. Спокойная цветная головоломка на 40 уровней.", "press.rr.short": "Поведи выживших после краха: добывай, выращивай, строй и отбивайся от рейдеров.", "press.cl.short": "Собери армию, сражайся с лордами и бандитами и верни утраченную корону рода.", "press.rr.long": "Rustroot — симулятор выживания колонии с видом сверху, созданный для телефонов. Колонисты едят, спят, устают, дружат и срываются от стресса. Разбирай руины, выращивай еду, строй стены, мастерские и турели, исследуй технологии трёх эпох, отбивайся от рейдеров и суровых зим и отправляй караваны по карте мира. Полностью без интернета.", "press.cl.long": "Crownless — средневековая песочница, стратегия и RPG для телефонов. Живой 3D-мир: пять королевств, 74 города, деревни и замка и 15 лордов со своими планами. Нанимай пехоту, лучников и конницу, сражайся в битвах в реальном времени, осаждай замки, торгуй и выполняй задания. Полностью без интернета, без рекламы.", "kofi.eyebrow": "Поддержать студию", "kofi.title": "Помогите нам делать новые игры", "kofi.lead": "Если вам нравятся наши игры, вы можете поддержать ATTA CORP на Ko-fi — это помогает выпускать обновления и новые проекты.", "kofi.btn": "Поддержать на Ko-fi", "kofi.short": "Поддержать на Ko-fi"};
(function(){
"use strict";
function setLang(l){
  if(l!=="ru")l="en";
  var d=l==="ru"?RU:EN;
  document.querySelectorAll("[data-i18n],[data-i18n-html]").forEach(function(n){
    var k=n.getAttribute("data-i18n");
    if(k){if(d[k]!=null)n.textContent=d[k];}
    else{k=n.getAttribute("data-i18n-html");if(d[k]!=null)n.innerHTML=d[k];}
  });
  document.documentElement.lang=l;
  var te=document.documentElement.getAttribute("data-title-"+l);
  if(te)document.title=te;
  var de=document.documentElement.getAttribute("data-desc-"+l);
  var md=document.querySelector('meta[name="description"]');
  if(de&&md)md.setAttribute("content",de);
  document.querySelectorAll("[data-i18n-aria]").forEach(function(n){
    var k=n.getAttribute("data-i18n-aria");
    if(k&&d[k]!=null)n.setAttribute("aria-label",d[k]);
  });
  document.querySelectorAll(".lang button").forEach(function(b){b.setAttribute("aria-pressed",String(b.dataset.lang===l));});
  try{localStorage.setItem("atta-lang",l);}catch(e){}
}
document.querySelectorAll(".lang button").forEach(function(b){b.addEventListener("click",function(){setLang(b.dataset.lang);});});
var saved=null;try{saved=localStorage.getItem("atta-lang");}catch(e){}
setLang(saved||"en");

var tabs=document.getElementById("tabs"),menuBtn=document.querySelector(".menu-btn");
function closeMenu(){if(!tabs||!menuBtn)return;tabs.classList.remove("open");menuBtn.setAttribute("aria-expanded","false");}
if(menuBtn){menuBtn.addEventListener("click",function(){var o=!tabs.classList.contains("open");tabs.classList.toggle("open",o);menuBtn.setAttribute("aria-expanded",String(o));});}
document.addEventListener("keydown",function(e){if(e.key==="Escape"){closeMenu();closeLightbox();}});
document.addEventListener("click",function(e){if(!e.target.closest(".nav"))closeMenu();});

var hero=document.getElementById("hero");
if(hero){
  var slides=[].slice.call(hero.querySelectorAll(".hero-slide"));
  var dots=hero.querySelector(".hero-dots");
  var i=0,timer=0,reduce=window.matchMedia("(prefers-reduced-motion: reduce)");
  slides.forEach(function(_,idx){
    var b=document.createElement("button");
    b.type="button";b.setAttribute("aria-label","Slide "+(idx+1));
    b.addEventListener("click",function(){go(idx,true);});
    dots.appendChild(b);
  });
  function go(n,user){
    i=(n+slides.length)%slides.length;
    slides.forEach(function(s,k){s.classList.toggle("is-active",k===i);s.setAttribute("aria-hidden",String(k!==i));});
    [].forEach.call(dots.children,function(d,k){if(k===i)d.setAttribute("aria-current","true");else d.removeAttribute("aria-current");});
    if(user)restart();
  }
  function next(){go(i+1,false);}
  function restart(){
    stop();
    if(!reduce.matches)timer=setInterval(next,6500);
  }
  function stop(){if(timer){clearInterval(timer);timer=0;}}
  hero.querySelector(".hero-prev").addEventListener("click",function(){go(i-1,true);});
  hero.querySelector(".hero-next").addEventListener("click",function(){go(i+1,true);});
  hero.addEventListener("mouseenter",stop);
  hero.addEventListener("mouseleave",restart);
  hero.addEventListener("focusin",stop);
  hero.addEventListener("focusout",function(e){if(!hero.contains(e.relatedTarget))restart();});
  var sx=0,sy=0;
  hero.addEventListener("touchstart",function(e){sx=e.changedTouches[0].clientX;sy=e.changedTouches[0].clientY;},{passive:true});
  hero.addEventListener("touchend",function(e){
    var dx=e.changedTouches[0].clientX-sx,dy=e.changedTouches[0].clientY-sy;
    if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy))go(i+(dx<0?1:-1),true);
  },{passive:true});
  go(0,false);restart();
}

var lb, lbImg, lbIndex=0, lbSet=[];
function ensureLightbox(){
  if(lb)return;
  lb=document.createElement("div");
  lb.className="lightbox";lb.setAttribute("role","dialog");lb.setAttribute("aria-modal","true");
  lb.innerHTML='<button type="button" class="lb-close">Close</button><button type="button" class="lb-prev" aria-label="Previous">‹</button><img alt=""><button type="button" class="lb-next" aria-label="Next">›</button>';
  document.body.appendChild(lb);
  lbImg=lb.querySelector("img");
  lb.querySelector(".lb-close").addEventListener("click",closeLightbox);
  lb.querySelector(".lb-prev").addEventListener("click",function(){showLB(lbIndex-1);});
  lb.querySelector(".lb-next").addEventListener("click",function(){showLB(lbIndex+1);});
  lb.addEventListener("click",function(e){if(e.target===lb)closeLightbox();});
  var l=(document.documentElement.lang==="ru")?"ru":"en";
  var d=l==="ru"?RU:EN;
  if(d["gallery.close"])lb.querySelector(".lb-close").textContent=d["gallery.close"];
  if(d["gallery.prev"])lb.querySelector(".lb-prev").setAttribute("aria-label",d["gallery.prev"]);
  if(d["gallery.next"])lb.querySelector(".lb-next").setAttribute("aria-label",d["gallery.next"]);
}
function showLB(n){
  if(!lbSet.length)return;
  lbIndex=(n+lbSet.length)%lbSet.length;
  var el=lbSet[lbIndex];
  lbImg.src=el.getAttribute("src");
  lbImg.alt=el.getAttribute("alt")||"";
}
function openLightbox(imgs, index){
  ensureLightbox();
  lbSet=imgs;showLB(index);
  lb.classList.add("is-open");
  document.body.style.overflow="hidden";
  lb.querySelector(".lb-close").focus();
}
function closeLightbox(){
  if(!lb)return;
  lb.classList.remove("is-open");
  document.body.style.overflow="";
  if(lbImg)lbImg.src="";
}
document.addEventListener("keydown",function(e){
  if(!lb||!lb.classList.contains("is-open"))return;
  if(e.key==="ArrowLeft")showLB(lbIndex-1);
  if(e.key==="ArrowRight")showLB(lbIndex+1);
});
var gal=document.getElementById("gallery");
if(gal){
  var shots=[].slice.call(gal.querySelectorAll("img"));
  shots.forEach(function(img,idx){img.addEventListener("click",function(){openLightbox(shots,idx);});});
}

var cv=document.getElementById("bg");
if(cv){
  var ctx=cv.getContext("2d");
  var reduce=window.matchMedia("(prefers-reduced-motion: reduce)");
  var COLORS=["#7c6cff","#00d2c8","#ffcf6a","#ff6f73","#7ad0a8","#6a8bf0","#ff7ac8"];
  var W=0,H=0,DPR=1,CELL=64,cols=0,rows=0,blocks=[],sprites={},path=null,raf=0,last=0,t0=performance.now();
  function sprite(color,size){
    var key=color+size;if(sprites[key])return sprites[key];
    var pad=size*0.9,s=Math.ceil((size+pad*2)*DPR),c=document.createElement("canvas");c.width=c.height=s;
    var g=c.getContext("2d");g.scale(DPR,DPR);
    g.shadowColor=color;g.shadowBlur=size*0.8;g.fillStyle=color;
    var r=size*0.26,x=pad,y=pad;
    g.beginPath();g.moveTo(x+r,y);g.arcTo(x+size,y,x+size,y+size,r);g.arcTo(x+size,y+size,x,y+size,r);g.arcTo(x,y+size,x,y,r);g.arcTo(x,y,x+size,y,r);g.closePath();
    g.globalAlpha=0.9;g.fill();g.shadowBlur=0;g.globalAlpha=0.25;g.fillStyle="#fff";g.fillRect(x+size*0.18,y+size*0.14,size*0.4,size*0.1);
    sprites[key]={c:c,off:pad};return sprites[key];
  }
  function resize(){
    DPR=Math.min(window.devicePixelRatio||1,1.75);
    W=window.innerWidth;H=window.innerHeight;
    cv.width=Math.round(W*DPR);cv.height=Math.round(H*DPR);
    ctx.setTransform(DPR,0,0,DPR,0,0);
    CELL=W<600?52:68;cols=Math.ceil(W/CELL)+1;rows=Math.ceil(H/CELL)+1;
    sprites={};
    var n=Math.round(Math.min(18,Math.max(8,W*H/56000)));
    blocks=[];for(var i=0;i<n;i++)blocks.push(newBlock(true));
    path=newPath();
  }
  function rnd(a,b){return a+Math.random()*(b-a);}
  function newBlock(anywhere){
    var size=Math.round(rnd(W<600?16:20,W<600?34:46));
    return{x:rnd(0,W),y:anywhere?rnd(0,H):H+60,size:size,color:COLORS[(Math.random()*COLORS.length)|0],
      vx:rnd(-6,6),vy:rnd(-14,-5),rot:rnd(0,6.28),vr:rnd(-.15,.15),ph:rnd(0,6.28),a:rnd(.12,.32)};
  }
  function newPath(){
    var cx=(Math.random()*(cols-2)+1)|0,cy=(Math.random()*(rows-2)+1)|0,pts=[[cx,cy]],seen={},len=(rnd(10,20))|0;
    seen[cx+","+cy]=1;
    for(var i=0;i<len;i++){
      var dirs=[[1,0],[-1,0],[0,1],[0,-1]].filter(function(d){var nx=cx+d[0],ny=cy+d[1];return nx>=0&&ny>=0&&nx<cols&&ny<rows&&!seen[nx+","+ny];});
      if(!dirs.length)break;var d=dirs[(Math.random()*dirs.length)|0];cx+=d[0];cy+=d[1];seen[cx+","+cy]=1;pts.push([cx,cy]);
    }
    return{pts:pts,p:0,speed:rnd(2.2,3.4),hold:0,fade:1,color:COLORS[(Math.random()*COLORS.length)|0]};
  }
  function frame(now){
    var dt=Math.min(.05,(now-(last||now))/1000);last=now;
    var t=(now-t0)/1000;
    ctx.clearRect(0,0,W,H);
    var hue=(t*8)%360;
    var blobs=[[.2+.08*Math.sin(t*.13),.25+.06*Math.cos(t*.11),0],[.85+.06*Math.cos(t*.09),.7+.08*Math.sin(t*.12),120],[.6+.1*Math.sin(t*.07),.05+.05*Math.cos(t*.1),240]];
    var R=Math.max(W,H)*.65;
    for(var b=0;b<3;b++){
      var bx=blobs[b][0]*W,by=blobs[b][1]*H,g=ctx.createRadialGradient(bx,by,0,bx,by,R);
      g.addColorStop(0,"hsla("+((hue+blobs[b][2])%360)+",80%,55%,.10)");g.addColorStop(1,"hsla("+((hue+blobs[b][2])%360)+",80%,40%,0)");
      ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    }
    ctx.strokeStyle="rgba(255,255,255,.03)";ctx.lineWidth=1;ctx.beginPath();
    for(var x=0;x<=cols;x++){ctx.moveTo(x*CELL+.5,0);ctx.lineTo(x*CELL+.5,H);}
    for(var y=0;y<=rows;y++){ctx.moveTo(0,y*CELL+.5);ctx.lineTo(W,y*CELL+.5);}
    ctx.stroke();
    drawPath(dt);
    for(var i=0;i<blocks.length;i++){
      var k=blocks[i];k.x+=k.vx*dt;k.y+=k.vy*dt;k.rot+=k.vr*dt;
      if(k.y<-80||k.x<-80||k.x>W+80){blocks[i]=newBlock(false);continue;}
      var s=sprite(k.color,k.size);
      ctx.save();ctx.globalAlpha=k.a*(.75+.25*Math.sin(t*.8+k.ph));ctx.translate(k.x,k.y);ctx.rotate(k.rot);
      ctx.drawImage(s.c,-(k.size/2+s.off),-(k.size/2+s.off),k.size+s.off*2,k.size+s.off*2);ctx.restore();
    }
    ctx.globalAlpha=1;
  }
  function drawPath(dt){
    var P=path,n=P.pts.length;if(n<2)return;
    if(P.p<n-1)P.p=Math.min(n-1,P.p+P.speed*dt);else if(P.hold<1.6)P.hold+=dt;else{P.fade-=dt*.8;if(P.fade<=0){path=newPath();return;}}
    var whole=Math.floor(P.p),frac=P.p-whole,half=CELL/2,pad=CELL*.14;
    ctx.globalAlpha=.08*P.fade;ctx.fillStyle=P.color;
    for(var i=0;i<=whole;i++){var c=P.pts[i];roundRect(c[0]*CELL+pad,c[1]*CELL+pad,CELL-pad*2,CELL-pad*2,CELL*.2);ctx.fill();}
    ctx.globalAlpha=.32*P.fade;ctx.strokeStyle=P.color;ctx.lineWidth=Math.max(4,CELL*.12);ctx.lineCap="round";ctx.lineJoin="round";
    ctx.shadowColor=P.color;ctx.shadowBlur=10;
    ctx.beginPath();ctx.moveTo(P.pts[0][0]*CELL+half,P.pts[0][1]*CELL+half);
    for(i=1;i<=whole;i++)ctx.lineTo(P.pts[i][0]*CELL+half,P.pts[i][1]*CELL+half);
    var hx,hy;
    if(whole<n-1){var a=P.pts[whole],b=P.pts[whole+1];hx=(a[0]+(b[0]-a[0])*frac)*CELL+half;hy=(a[1]+(b[1]-a[1])*frac)*CELL+half;ctx.lineTo(hx,hy);}
    else{hx=P.pts[n-1][0]*CELL+half;hy=P.pts[n-1][1]*CELL+half;}
    ctx.stroke();ctx.shadowBlur=0;
    ctx.globalAlpha=.5*P.fade;ctx.fillStyle="#fff";ctx.beginPath();ctx.arc(hx,hy,Math.max(4,CELL*.1),0,6.283);ctx.fill();
    ctx.globalAlpha=1;
  }
  function roundRect(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath();}
  function loop(now){frame(now);raf=requestAnimationFrame(loop);}
  function start(){stop();last=0;if(reduce.matches||document.hidden){if(reduce.matches){if(path){path.p=path.pts.length-1;}frame(performance.now());}return;}raf=requestAnimationFrame(loop);}
  function stop(){if(raf)cancelAnimationFrame(raf);raf=0;}
  var rt;window.addEventListener("resize",function(){clearTimeout(rt);rt=setTimeout(function(){resize();start();},150);});
  document.addEventListener("visibilitychange",function(){if(document.hidden)stop();else start();});
  if(reduce.addEventListener)reduce.addEventListener("change",start);
  resize();start();
}
})();

/* gameplay video: play muted only while visible */
(function(){
var vids=document.querySelectorAll("video[data-autoplay]");
if(!vids.length||!("IntersectionObserver" in window))return;
if(window.matchMedia("(prefers-reduced-motion: reduce)").matches)return;
var io=new IntersectionObserver(function(es){es.forEach(function(e){var v=e.target;if(e.isIntersecting){v.muted=true;var p=v.play();if(p&&p.catch)p.catch(function(){});}else if(!v.paused&&!v.dataset.user){v.pause();}});},{threshold:.5});
vids.forEach(function(v){v.addEventListener("click",function(){v.dataset.user="1";});io.observe(v);});
})();

/* localized dates */
(function(){
function fmt(){var l=document.documentElement.lang==="ru"?"ru-RU":"en-US";document.querySelectorAll("time[datetime]").forEach(function(t){var d=new Date(t.getAttribute("datetime")+"T12:00:00");if(!isNaN(d))t.textContent=d.toLocaleDateString(l,{year:"numeric",month:"long",day:"numeric"});});}
document.querySelectorAll(".lang button").forEach(function(b){b.addEventListener("click",fmt);});fmt();
})();
